head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > P > delimiter]<br/>Calendar 컴포넌트 하단에 표시되는 선택일의 연/월/일을 구분하는 구분자를 설정합니다.",
    "validation" : [
        "값을 설정하지 않으면 기본값 '/' 가 구분자로 적용됩니다.",
        "문자열 설정 시 컴포넌트 하단 선택일의 연(yyyy), 월(MM), 일(dd) 사이에 해당 문자열이 구분자로 삽입됩니다.",
        "displayFormat 속성 설정 시 컴포넌트의 날짜 편집 영역에 delimiter 가 적용되지 않습니다. (displayFormat 우선)",
        "displayFormatFunc 속성 설정 시 컴포넌트의 날짜 편집 영역에 delimiter 가 적용되지 않습니다. (displayFormatFunc 우선)",
        "displayFormat 미설정 + calendarValueType='yearMonth' 이면 'yyyy{d}MM' 포맷이 displayFormat 속성의 기본값으로 설정됩니다. ({d} 는 delimiter)",
        "displayFormat 미설정 + calendarValueType 그외 값이면 'yyyy{d}MM{d}dd' 포맷이 displayFormat 속성의 기본값으로 설정됩니다. ({d} 는 delimiter)",
        "delimiter 속성은 화면 표시용 구분자로만 사용되며, getValue() 메소드가 반환하는 데이터 값에는 영향을 미치지 않습니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // displayFormatFunc 용 글로벌 함수 등록 (delimiter 무시 검증용)
    scwin.formatByType = function (calendarValueType) {
        if (calendarValueType === 'yearMonth') return 'yyyy.MM';
        return 'yyyy.MM.dd';
    };

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        delimiter : con_delimiter.getValue(),
        calendarValueType : con_calendarValueType.getText(),
        displayFormat : con_displayFormat.getValue(),
        displayFormatFunc : con_displayFormatFunc.getValue()
    }

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onclick"]);

    await $c.gcm.createBasicCalendar(cList, eList);
}



scwin.btn_getInfo_onclick = function (e) {
    let calendarRender = target1.render;
    let currentDateElem = calendarRender.querySelector('[id$="_currentDate"]');

    // validation: 미설정 시 기본값 '/' 적용 / 문자열 설정 시 연/월/일 사이에 구분자로 삽입됨
    let delimiterOpt = target1.options.delimiter;
    let displayedText = currentDateElem ? currentDateElem.textContent : '없음';
    wf_body_bottom.getObj("scwin").setReturnValue("[하단 선택일 표시 텍스트] '" + displayedText + "' (delimiter 옵션값='" + delimiterOpt + "'" + (delimiterOpt === '' ? ", 미설정 → 기본 '/' 적용" : ", 설정값 적용") + ")");

    // validation: displayFormat 미설정 + calendarValueType=yearMonth → 'yyyy{d}MM' 기본 / 그외 → 'yyyy{d}MM{d}dd' 기본
    //             displayFormat 설정 시 / displayFormatFunc 설정 시 → delimiter 적용 안됨 (displayFormat 그대로 사용)
    let displayFormatOpt = target1.options.displayFormat;
    let displayFormatFuncOpt = target1.options.displayFormatFunc;
    let cvType = target1.options.calendarValueType;
    let delimiterEffective = (con_displayFormat.getValue() === '' && con_displayFormatFunc.getValue() === '');
    wf_body_bottom.getObj("scwin").setReturnValue("[displayFormat 적용 포맷] '" + displayFormatOpt + "' (calendarValueType='" + cvType + "', displayFormatFunc='" + displayFormatFuncOpt + "', delimiter 적용여부=" + (delimiterEffective ? "적용됨" : "적용 안됨 (displayFormat/Func 우선)") + ")");

    // validation: delimiter 는 화면 표시용, getValue() 반환값에는 영향 없음
    let rawValue = target1.getValue();
    wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 반환] '" + rawValue + "' (구분자 없는 raw 데이터, delimiter 무관)");
}
